/** Valores de RESULT documentados en el encabezado de L050. */
public enum ResultadoL050 {
    OK(0), FUNCION_INCORRECTA(1), TIPO_PROCESO_INCORRECTO(2), TIPO_PROCESO_CON_FUNCION_INCORRECTO(3),
    NUMERO_COPIA_INCORRECTO(4), CLIENTE_INCORRECTO(5), IMPORTE_INCORRECTO(6),
    IND_DEP_RET_INCORRECTO(7), IND_MOV_FORZADO_INCORRECTO(8), CLIENTE_BLOQUEADO_RETIRO(9),
    LIMITE_RETIRO_DIARIO(10), LIMITE_RETIRO_MENSUAL(11), ERROR_ABRIR_BD(12), ERROR_FECHA_B02(13),
    CLIENTE_A_ELIMINAR_NO_EXISTE(14), ERROR_BD_B52_B55_B53(15), ERROR_CERRAR_BD(16),
    FECHA_ELIMINACION_INCORRECTA(17), IND_INC_DEC_INCORRECTO(18), CLIENTE_NO_EXISTE(19),
    ERROR_L010_SOLSECDIA(20), IND_REPLICA_ERRONEO(21), LIMITE_SECUENCIAL_REPLICA(22), HI_INVALIDO(23);

    private final int codigo;
    ResultadoL050(int codigo) { this.codigo = codigo; }
    public int codigo() { return codigo; }
}

/** EA_ENTRADAV: posiciones fijas en dígitos EBCDIC. */
public record SolicitudValRetDep(
        int funcion,                 // [0..1]   1 alta, 2 eliminación, 3 consulta, 4 cambio TP/UG/CSI
        String cliente,              // [2..13]  12 dígitos: String para conservar ceros
        BigDecimal importe,          // [14..31] 18 dígitos con 2 decimales implícitos
        int indDepRet,               // [32..33] 1 depósito, 2 retiro
        int bancoEmisor,             // [34..37]
        int movForzado,              // [38..39] 0 o 1
        TipoProceso tipoProceso,     // [40..41] 0 línea, 1 batch, 2 prelínea, 3 fin de batch
        int numCopia, int sucursalOperador, int cajaOperador,
        int tipoPersona, int ubicacionGeo, int csi) {}

/** EA_SALIDAV. */
public record RespuestaValRetDep(int indRiesgo,          // [0..1]   0 no, 1 banco de riesgo
                                 BigDecimal saldoCongelado, // [2..19] 9(16)V99
                                 int indValida,          // [20..21] 0..5
                                 int indSupLim,          // [22..23] 0 no, 1 diario, 2 mensual, 3 ambos
                                 ResultadoL050 resultado) {}

@Service
@RequiredArgsConstructor
public class LimitesDepRetService {

    private final EstadoLibreria estado;              // B_PRIMER_LLAMADO, I_LINEA_BATCH_E
    private final ValidacionMovimiento validacion;    // PROCESA_MOVIMIENTO
    private final CambioCaracteristicas cambio;       // PROCESA_FUNCION_4
    private final RespuestaBuilder respuesta;         // ARMA_RESPUESTA_VALIDA

    /** S500L050VALRETDEP(ENTRADA, SALIDA): misma firma lógica que exponía la librería. */
    public RespuestaValRetDep valRetDep(SolicitudValRetDep s) {
        Contexto ctx = new Contexto(s);               // reemplaza LIMPIA_VARIABLES_VALIDA

        if (s.funcion() < 1 || s.funcion() > 4) {
            ctx.resultado(ResultadoL050.FUNCION_INCORRECTA);
        } else if (s.funcion() == 4) {
            cambio.procesa(ctx);
        } else if (s.tipoProceso() == null) {         // fuera de 0..3
            ctx.resultado(ResultadoL050.TIPO_PROCESO_INCORRECTO);
        } else if (s.tipoProceso() == TipoProceso.FIN_BATCH && s.funcion() <= 2) {
            estado.cambiaTipoProceso(s.tipoProceso());
            ctx.resultado(ResultadoL050.TIPO_PROCESO_CON_FUNCION_INCORRECTO);
        } else {
            if (estado.primerLlamado() || s.funcion() == 3 || estado.tipoProceso() != s.tipoProceso()) {
                estado.cambiaTipoProceso(s.tipoProceso());    // abre o cambia de base: línea o auxiliar
            }
            if (s.funcion() <= 2) validacion.procesa(ctx);
        }
        return respuesta.arma(ctx);
    }
}

/** VALIDA_INFORMACION_VALIDA: la primera condición que falla decide el resultado. */
static Optional<ResultadoL050> validaSolicitud(SolicitudValRetDep s) {
    if (new BigInteger(s.cliente()).signum() <= 0)   return Optional.of(ResultadoL050.CLIENTE_INCORRECTO);
    if (s.importe().signum() <= 0)                   return Optional.of(ResultadoL050.IMPORTE_INCORRECTO);
    if (s.indDepRet() != 1 && s.indDepRet() != 2)    return Optional.of(ResultadoL050.IND_DEP_RET_INCORRECTO);
    if (s.movForzado() != 0 && s.movForzado() != 1)  return Optional.of(ResultadoL050.IND_MOV_FORZADO_INCORRECTO);
    return Optional.empty();
}

public interface B55LimiteRepository extends JpaRepository<B55Limite, B55LimiteId> {
    /** FIND B55SXLIM AT B55-FECHA = ... AND B55-TIP-PER = ... AND B55-TIP-OPER = ... AND B55-UBI-GEO = ... */
    Optional<B55Limite> findByFechaAndTipoPersonaAndTipoOperacionAndUbicacionGeo(
            LocalDate fecha, int tipoPersona, int tipoOperacion, int ubicacionGeo);
}

@Component
@RequiredArgsConstructor
class LimitesResolver {
    private final B55LimiteRepository b55;

    /** Solo completa el límite que el cliente no trae en B52 (valor 0). */
    Limites completa(Limites deB52, Contexto ctx) {
        if (deB52.dia().signum() > 0 && deB52.mes().signum() > 0) return deB52;
        Optional<Limites> b55Ug = busca(ctx, ctx.ubicacionGeo());
        Optional<Limites> b55 = b55Ug.isPresent() || ctx.ubicacionGeo() == 0
                ? b55Ug
                : busca(ctx, 0);                     // segundo intento con ubicación 0
        return b55.map(l -> deB52.completaCon(l)).orElse(deB52);   // sin límite si no hay registro
    }

    private Optional<Limites> busca(Contexto ctx, int ug) {
        try {
            return b55.findByFechaAndTipoPersonaAndTipoOperacionAndUbicacionGeo(
                    ctx.fechaLinea(), ctx.tipoPersona(), ctx.indDepRet(), ug).map(B55Limite::limites);
        } catch (DataAccessException e) {
            ctx.resultado(ResultadoL050.ERROR_BD_B52_B55_B53);      // I_RESULT := 15
            throw new ErrorBaseLimites(e);           // corta el segundo intento, como I_RESULT NEQ 15
        }
    }
}

/** PROCESA_DEPOSITO. Importes en BigDecimal escala 2; ALGOL usa DOUBLE. */
void procesaDeposito(Contexto ctx, Limites lim, Acumulados acum) {
    BigDecimal importe = ctx.importe();

    if (lim.dia().signum() > 0) {
        BigDecimal total = acum.dia().add(importe);
        if (total.compareTo(lim.dia()) >= 0) {
            BigDecimal excedente = total.subtract(lim.dia());
            ctx.saldoCongelado(excedente.min(importe));      // nunca más que el propio depósito
            ctx.indSupLim(1);
            verificaAcumSaldo(ctx, OpcionAcum.SALDO_CONGELADO);
        }
    }
    if (lim.mes().signum() > 0) {
        BigDecimal total = acum.mes().add(importe);
        if (total.compareTo(lim.mes()) >= 0) {
            ctx.indSupLim(ctx.indSupLim() == 1 ? 3 : 2);    // solo indicador: no congela
        }
    }
}

/** PROCESA_RETIRO. */
void procesaRetiro(Contexto ctx, Limites lim, Acumulados acum) {
    if (acum.bloqueado()) {                                   // B52-IND-BLOQUEO <> 0
        ctx.resultado(ResultadoL050.CLIENTE_BLOQUEADO_RETIRO);   // 9
        ctx.indIncRet(3);
        ctx.eventoDosACuatro();
        return;
    }
    if (ctx.movForzado() == 1 && estado.tipoProceso() == TipoProceso.PRELINEA) {
        return;                                               // forzado en prelínea: sin validar límites
    }
    if (lim.dia().signum() > 0 && acum.dia().add(ctx.importe()).compareTo(lim.dia()) >= 0) {
        ctx.resultado(ResultadoL050.LIMITE_RETIRO_DIARIO);    // 10
        ctx.indIncRet(1); ctx.indSupLim(1);
        ctx.eventoDosACuatro();
    }
    if (lim.mes().signum() > 0 && acum.mes().add(ctx.importe()).compareTo(lim.mes()) >= 0) {
        if (ctx.indIncRet() == 1) {
            ctx.indIncRet(3); ctx.indSupLim(3);
        } else {
            // El fuente asigna 10 también aquí; RESULT 11 (mensual) solo se usa en PROCESA_FUNCION_4.
            ctx.resultado(props.resultadoMensualCompatible()
                    ? ResultadoL050.LIMITE_RETIRO_DIARIO : ResultadoL050.LIMITE_RETIRO_MENSUAL);
            ctx.indIncRet(2); ctx.indSupLim(2);
        }
        ctx.eventoDosACuatro();
    }
}

/** Tope de los acumulados en B52: DF_MAX_ACUM = @@16 - .01. */
static final BigDecimal MAX_ACUM = new BigDecimal("9999999999999999.99");

/** PROCESA_DEPOSITO_RETIRO: antes de comparar, ajusta los acumulados a la fecha en línea. */
Acumulados vigentes(Contexto ctx, Acumulados acum) {
    if (ctx.evento() == 1) return acum;                       // cliente nuevo: sin acumulados
    YearMonth mesLinea = YearMonth.from(ctx.fechaLinea());
    YearMonth mesAcum  = YearMonth.from(acum.fecha());
    Acumulados a;
    if (!mesLinea.equals(mesAcum)) {
        a = acum.sinMensual().sinDiario();                    // FIN_MES
    } else if (!ctx.fechaLinea().equals(acum.fecha()) || ctx.evento() == 2) {
        a = acum.sinDiario();                                 // FIN_DIA o evento 2
    } else {
        a = acum;
    }
    // VERIFICA_ACUM_SALDO(1): con ambos acumulados saturados el movimiento se valida
    // pero no se guarda (IND_VALIDA 3), salvo tipo de persona 0.
    boolean saturado = a.dia().compareTo(MAX_ACUM) == 0 && a.mes().compareTo(MAX_ACUM) == 0;
    if (saturado && ctx.tipoPersona() != 0) ctx.indValida(3);
    return a;
}

/** Reemplaza el arreglo en memoria por una tabla outbox: el movimiento sobrevive a una caída. */
@Entity
@Table(name = "l050_movimiento_pendiente")
public class MovimientoPendiente {
    @Id @GeneratedValue Long id;
    String cliente;                       // DF_A_CLIENTE      12 dígitos
    LocalDate fechaMov;                   // DF_A_FECHA_MOV    I_B02_FECHA_LINEA
    @Column(precision = 18, scale = 2) BigDecimal importe;          // DF_A_IMPORTE
    int indDepRet, indIncRet, evento, guarda, tipoPersona, ubicacionGeo, csi;
    @Column(precision = 18, scale = 2) BigDecimal saldoCongelado;   // DF_A_SADO_CONG
}

@Component
@RequiredArgsConstructor
class MovimientosPendientes {
    private final MovimientoPendienteRepository repo;
    private final L050Properties props;                // capacidad: 500 (DF_TAM_REGISTR)

    /** GUARDA_MOV_ARREGLO: si se alcanza la capacidad, se valida pero no se guarda (IND_VALIDA 3). */
    @Transactional(propagation = Propagation.MANDATORY)    // misma transacción que el movimiento de P010
    boolean guarda(Contexto ctx) {
        if (repo.count() >= props.capacidad()) {
            log.warn("ARREGLO SIN ESPACIO");
            ctx.indValida(3);
            return false;
        }
        repo.save(MovimientoPendiente.desde(ctx));
        return true;                                    // CAUSE(E_PROCESA_MOV): lo toma AcumuladosWorker
    }
}

@Component
@RequiredArgsConstructor
class AcumuladosWorker {
    private final MovimientoPendienteRepository pendientes;
    private final ClienteLimiteRepository b52;

    /** LEE_ARREGLO + ACUM_DEP_RET, en orden de llegada. */
    @Scheduled(fixedDelayString = "${l050.worker.intervalo:PT1S}")
    @Transactional
    public void procesa() {
        for (MovimientoPendiente m : pendientes.findTop100ByOrderByIdAsc()) {
            ClienteLimite c = b52.findByClienteForUpdate(m.cliente)          // LOCK del registro B52
                    .orElseGet(() -> ClienteLimite.nuevo(m));
            c.reiniciaSiCambio(m.fechaMov, m.evento);                        // FIN_MES / FIN_DIA / evento 2
            if (m.indDepRet == 1) {
                c.sumaDeposito(m.importe, m.saldoCongelado);                 // DEP_DIA, DEP_MEN, SDO_CON_DEP
            } else {
                c.sumaRetiro(m.importe);                                     // RET_DIA, RET_MEN
            }
            c.saturaEn(MAX_ACUM);                                            // VALIDA_ACUMULADOS_AS
            pendientes.delete(m);    // si la base falla, la transacción se revierte y el pendiente se conserva
        }
    }
}
